import sys
import os

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

os.environ['TRANSFORMERS_OFFLINE'] = '1'
os.environ['HF_HUB_OFFLINE'] = '1'
os.environ['HF_DATASETS_OFFLINE'] = '1'

from keyword_extraction import MultilingualKeywordSet

model_cache_path = './model_cache2'

def enter_example():
    os.environ['HF_HUB_DISABLE_TELEMETRY'] = '1'
    os.environ['HF_HUB_DISABLE_PROGRESS_BARS'] = '1'
    os.environ['TOKENIZERS_PARALLELISM'] = 'false'

    # Это длинный абзац о машинном обучении. Он охватывает несколько тем, включая нейронные сети, глубокие нейронные сети и сверточные нейронные сети. Цель состоит в том, чтобы извлечь значимые ключевые слова, такие как алгоритмы машинного обучения и методы глубокого обучения, из длинных текстов.
    # Современные технологии искусственного интеллекта и машинного обучения стремительно трансформируют различные отрасли промышленности и науки. Глубокие нейронные сети, которые представляют собой многослойные архитектуры с десятками и даже сотнями слоёв, демонстрируют впечатляющие результаты в распознавании образов, обработке естественного языка и компьютерном зрении. Свёрточные нейронные сети, впервые предложенные Яном Лекуном в конце двадцатого века, стали основой для большинства современных систем компьютерного зрения, включая распознавание лиц, автоматическую аннотацию изображений и диагностику медицинских снимков. Рекуррентные нейронные сети и их более совершенные варианты, такие как LSTM и GRU, успешно применяются для анализа последовательных данных, включая временные ряды, тексты на естественном языке и геномные последовательности. Методы глубокого обучения с подкреплением позволили создать алгоритмы, которые превосходят человека в таких сложных играх, как го, шахматы и различные видеоигры от компании Blizzard. Трансформеры, архитектура которых была представлена в знаменитой статье Attention Is All You Need, произвели настоящую революцию в области обработки естественного языка, что привело к созданию таких моделей, как BERT, GPT, T5 и многих других. Эти модели используют механизм внимания, который позволяет эффективно обрабатывать длинные последовательности и улавливать сложные зависимости между элементами текста.
    # В последние годы наблюдается значительный прогресс в области квантовых вычислений и их потенциального применения для решения сложных оптимизационных задач. Квантовые процессоры, основанные на сверхпроводящих кубитах и захваченных ионах, постепенно набирают вычислительную мощность, приближаясь к так называемому квантовому превосходству. Исследователи из Google впервые продемонстрировали квантовое превосходство в 2019 году, когда их 53-кубитный процессор Sycamore выполнил специфическую задачу за 200 секунд, на решение которой у самого мощного классического суперкомпьютера потребовалось бы около десяти тысяч лет. Однако критики отмечают, что эта задача была специально подобрана для квантового компьютера и не имеет практического применения. Тем не менее, учёные активно работают над созданием отказоустойчивых квантовых компьютеров с коррекцией ошибок, что является одним из главных препятствий на пути к практическому использованию квантовых алгоритмов. Параллельно развиваются и гибридные подходы, сочетающие классические и квантовые вычисления, которые уже сейчас могут применяться для оптимизации логистических цепочек, моделирования молекулярных структур в фармацевтике и решения других прикладных задач.
    # Цифровая трансформация бизнеса в эпоху четвёртой промышленной революции требует от компаний не только внедрения новых технологий, но и пересмотра фундаментальных бизнес-моделей и организационных структур. Большие данные, аналитика в реальном времени и предиктивное моделирование становятся ключевыми инструментами для принятия стратегических решений в условиях высокой неопределённости и турбулентности рынков. Пандемия коронавируса значительно ускорила процессы цифровизации во всех секторах экономики, от розничной торговли и образования до здравоохранения и государственного управления. Компании, которые раньше игнорировали необходимость развития онлайн-каналов продаж и удалённых форматов работы, оказались в крайне уязвимом положении. В то же время лидеры цифровой экономики, такие как Amazon, Microsoft и китайские технологические гиганты, смогли не только сохранить, но и значительно нарастить свои рыночные позиции. Интересно отметить, что внедрение технологий искусственного интеллекта и роботизации процессов пока что приводит к созданию новых рабочих мест и трансформации существующих профессий, а не к массовой безработице, как прогнозировали некоторые пессимистичные эксперты в начале двухтысячных годов.
    # Прорывы в области генной инженерии и персонализированной медицины открывают беспрецедентные возможности для лечения ранее неизлечимых заболеваний. Технология редактирования генома CRISPR-Cas9, открытая Эммануэль Шарпантье и Дженнифер Дудной, позволяет вносить точные изменения в ДНК живых организмов, открывая путь к исправлению генетических мутаций, вызывающих наследственные заболевания. Уже проводятся клинические испытания методов терапии серповидноклеточной анемии, муковисцидоза и некоторых форм наследственной слепоты с использованием технологий генного редактирования. Параллельно развиваются методы иммунотерапии рака, включая CAR-T-клеточную терапию, при которой иммунные клетки пациента генетически модифицируются для более эффективного распознавания и уничтожения злокачественных опухолей. В онкологии также активно применяются алгоритмы машинного обучения для анализа медицинских изображений, что позволяет на ранних стадиях выявлять злокачественные новообразования и значительно повышает точность диагностики. Модели глубокого обучения способны различать доброкачественные и злокачественные образования на маммограммах и компьютерных томограммах с точностью, сопоставимой или даже превосходящей опытных радиологов.
    # Глобальное изменение климата и антропогенное воздействие на окружающую среду становятся одними из главных вызовов двадцать первого века, требующих безотлагательных и скоординированных действий на международном уровне. Концентрация парниковых газов в атмосфере достигла рекордных значений за последние восемьсот тысяч лет, что приводит к повышению средней температуры на планете, таянию ледников и учащению экстремальных погодных явлений. Участившиеся лесные пожары в Австралии и Сибири, разрушительные ураганы в Атлантике, наводнения в Европе и Юго-Восточной Азии напрямую связаны с климатическими изменениями. Учёные предупреждают, что если не принять решительных мер по сокращению выбросов углекислого газа и других парниковых газов, последствия будут катастрофическими для экосистем и человеческой цивилизации. В ответ на эту угрозу многие страны взяли на себя обязательства по достижению углеродной нейтральности к середине столетия, что предполагает масштабный переход к возобновляемым источникам энергии, электрификацию транспорта и повышение энергоэффективности промышленности и строительства.
    # И конечно же никто никогда не мог предположить, что старые методы и подходы окажутся полностью бесполезными в новой реальности. Однако тот самый наш опыт показывает, что не всё так просто и однозначно в этом вопросе. Мы долго обсуждали эту проблему и в итоге пришли к выводу, что нужно действовать незамедлительно. Сначала они попытались решить всё с помощью обычных алгоритмов, но потом поняли, что это был довольно наивный подход. В конце концов, как говорится, настоящие профессионалы всегда ищут нестандартные решения и не боятся экспериментировать. Именно поэтому было принято решение об использовании самых современных нейросетевых архитектур для обработки поступающих данных.
    # This is a longer paragraph about machine learning. It covers multiple topics including neural networks, deep neural networks, and convolutional neural networks. The goal is to extract meaningful keywords like machine learning algorithms and deep learning methods from longer texts.
    keyword_set = MultilingualKeywordSet(
        initial_keywords={
            'en': [],
            'ru': []
        },
        similarity_threshold=0.75,
        collocation_overlap_threshold=0.6,
        cache_folder=model_cache_path,
        embedding_model='cointegrated/rubert-tiny2',
        use_collocations=True,
        max_chunk_size=500
    )

    print("Enter your text: ")
    s = input()
    
    result = keyword_set.process_text(s)

    if 'keywords' in result and result['keywords']:
        for i, word in enumerate(result['keywords']):
            print(f"{i + 1}: {word}")
    else:
        print("No keywords found.")

if __name__ == "__main__":
    enter_example()